$utf8 = New-Object System.Text.UTF8Encoding $false
$files = @(Get-ChildItem "Assets/_Project" -Recurse -Include *.cs,*.md,*.mdc -File)
foreach ($extra in @(".cursor/rules/dark-matter-genesis-ui-palette.mdc", ".cursor/rules/skill-precedence.mdc")) {
  if (Test-Path $extra) { $files += Get-Item $extra }
}
$count = 0
foreach ($f in $files) {
  $c = [System.IO.File]::ReadAllText($f.FullName)
  $n = $c.Replace('SurvivalPioneerUiPalette','DarkMatterGenesisUiPalette').Replace('SurvivalPioneerEditorMenus','DarkMatterGenesisEditorMenus').Replace('SurvivalPioneerToolsWindow','DarkMatterGenesisToolsWindow')
  if ($n -ne $c) {
    [System.IO.File]::WriteAllText($f.FullName, $n, $utf8)
    $count++
  }
}
Write-Host "Updated $count files"

Write-Host "ON DISK:"; Get-ChildItem "Assets/_Project" -Recurse -Filter "*SurvivalPioneer*" -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName }
Get-ChildItem "Assets/_Project" -Recurse -Filter "*DarkMatterGenesis*" -ErrorAction SilentlyContinue | ForEach-Object { $_.Name }
Write-Host "---TRACKED---"; git ls-files "*SurvivalPioneer*" "*DarkMatterGenesis*"
Write-Host "---GUID compare---"
foreach ($pair in @(
  @("Assets/_Project/Editor/SurvivalPioneerEditorMenus.cs.meta","Assets/_Project/Editor/DarkMatterGenesisEditorMenus.cs.meta"),
  @("Assets/_Project/Editor/SurvivalPioneerToolsWindow.cs.meta","Assets/_Project/Editor/DarkMatterGenesisToolsWindow.cs.meta"),
  @("Assets/_Project/Scripts/UI/SurvivalPioneerUiPalette.cs.meta","Assets/_Project/Scripts/UI/DarkMatterGenesisUiPalette.cs.meta")
)) {
  $old=$pair[0]; $new=$pair[1]
  $og = if (Test-Path $old) { (Select-String -Path $old -Pattern '^guid:').Line } elseif (git show "HEAD:$old" 2>$null) { (git show "HEAD:$old" | Select-String '^guid:').Line } else { "MISSING" }
  # try previous commit for old
  $og = (git show "22180126b:$old" 2>$null | Select-String '^guid:').Line
  $ng = if (Test-Path $new) { (Select-String -Path $new -Pattern '^guid:').Line } else { "MISSING NEW" }
  Write-Host "$old -> $og"
  Write-Host "$new -> $ng"
}
